class RebootPower(RebootArgon):
    """Reboot power command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, expected_prompt=r"HUB-\d+.*\$"):
        """
        Reboot power in RFSW_CLI state.

        :param connection: moler connection to device, terminal when command is executed
        :param prompt: Prompt of the starting shell
        :param expected_prompt: Prompt of the target shell reached after entering Argon
        :param newline_chars: Characters to split lines
        """
        super(RebootPower, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                          expected_prompt=expected_prompt)

    def build_command_string(self):
        """
        Build string with command to send over conenction.

        :return: String with command.
        """
        return "reboot power"


